'use strict';
const TRIALS=[
 {name:'Meet your captain',fmt:1,reward:50,tip:'Watch one beast. Its attacks, dash, and signature ability happen automatically.',species:['troll']},
 {name:'Find your balance',fmt:3,reward:60,tip:'Try a frontliner, a damage dealer, and a support beast.',species:['golem','direwolf','unicorn']},
 {name:'Protect the back line',fmt:3,reward:75,tip:'Drag your toughest beast forward. Keep fragile allies behind it.',species:['minotaur','harpy','kirin']},
 {name:'Open the league gates',fmt:5,reward:90,tip:'Build your full five. Your first league season starts after this bout.',species:['troll','golem','direwolf','harpy','unicorn']}
];
const ARMORY_EARNINGS=300;
function campaignState(){if(!G)return null;if(!G.campaign){const earned=(G.ledger||[]).filter(l=>/Matchday|win|appearance|champion/i.test(l.label)&&l.amt>0).reduce((n,l)=>n+l.amt,0);G.campaign={version:1,preseason:4,earnedGold:G.season>1||G.day>=5?Math.max(earned,300):earned,paid:[]}}return G.campaign}
function inPreseason(){return campaignState()?.preseason<TRIALS.length}
function armoryUnlocked(){return !!G&&(campaignState().earnedGold>=ARMORY_EARNINGS||G.stash.length>0||Object.values(G.cons).some(Boolean)||clubBeasts().some(b=>Object.values(b.gear||{}).some(Boolean)))}
function campaignLabel(c){return c.kind==='trial'?`Preseason ${c.trial+1} / 4 · ${TRIALS[c.trial].name}`:c.kind==='league'?`Matchday ${c.r+1}`:`${G.cup?.name||'Cup'} · ${c.round}`}
const campaignNewGame=newGame;newGame=function(...args){campaignNewGame(...args);G.campaign={version:1,preseason:0,earnedGold:0,paid:[]};G.gold=0;G.lineups[1]=[G.clubs.P.roster[0]];G.lineups[3]=G.lineups[5].slice(0,3);for(const b of clubBeasts()){autoPick(b);autoTechniques(b)}G.news.unshift({s:1,d:1,text:'Four preseason bouts. Earn gold and powers before your league debut.',kind:'season'})};
const campaignOpen=openNext;openNext=function(){if(!inPreseason())return campaignOpen();const i=campaignState().preseason,t=TRIALS[i],id='TRAIN';if(G.clubs[id])for(const bid of G.clubs[id].roster)delete G.beasts[bid];const roster=t.species.map(sp=>genBeast(Math.max(15,TIERS[0].q-6+i*2),{sp,clubId:id,draft:true}).id);G.clubs[id]={id,name:['The Old Keepers','The Practice Pack','The Gate Wardens','The Trial Champions'][i],hue:180,roster};setPrematch({kind:'trial',trial:i,opp:id,fmt:t.fmt})};
const campaignFinish=finishMatch;finishMatch=function(S){const c=UI.ctx,state=campaignState(),key=`${G.season}:${G.day}:${c.kind}:${c.kind==='trial'?c.trial:c.kind==='league'?c.r:c.round+':'+c.opp}`;if(state.paid.includes(key))return;
 if(c.kind!=='trial'){campaignFinish(S);state.earnedGold+=UI.result.gold;state.paid.push(key);save();render();return}
 stopBattle();const rows=recordMatch(S,{fmt:c.fmt,training:true}),gold=TRIALS[c.trial].reward,champ=rows.filter(r=>r.team===0).sort((a,b)=>b.imp-a.imp)[0],b=G.beasts[champ.bid];
 if(!G.arenaRules&&!(b.rolls>0)){b.rolls=1;rollOffer(b)}
 G.gold+=gold;state.earnedGold+=gold;state.preseason=c.trial+1;state.paid.push(key);ledger(`Preseason ${c.trial+1} arena reward`,gold);
 UI.lvq=rows.filter(r=>r.team===0&&G.beasts[r.bid].rolls>0).map(r=>r.bid);UI.lvTotal=UI.lvq.length;UI.result={ctx:c,winner:S.winner,t:S.t,timeout:!!S.timeout,rows,gold,ren:0,mil:[],notes:[G.arenaRules?'Heroes who level up earn their own upgrade choice.':`${b.name} earned a new power. Choose one of three cards.`,state.preseason===4?'Preseason complete. Your league season is open.':'Your team is fully rested for the next preseason bout.'],ka:killsOf(S,0),kb:killsOf(S,1),purse:[['Preseason arena reward',gold]]};
 UI.mode='result';music(S.winner===0?'victory':'honor');save();render();window.scrollTo(0,0);
};
const campaignNext=resultNext;resultNext=function(){if(UI.result?.ctx.kind!=='trial')return campaignNext();UI.result=null;UI.ctx=null;UI.lvq=[];UI.mode='hub';UI.tab='club';save();render();window.scrollTo(0,0)};
function journeyHtml(){const c=campaignState(),stage=inPreseason()?0:curEvent()?.t==='league'?1:2;return `<div class="journey" aria-label="Campaign progress">${['Preseason','League season','Cup days','Build your legacy'].map((s,i)=>`<span class="${i===stage?'current':i<stage?'done':''}"><i>${i<stage?'✓':String(i+1).padStart(2,'0')}</i>${s}${i===0&&inPreseason()?` · ${c.preseason}/4`:''}</span>`).join('')}</div>`}
viewClub=function(){const c=campaignState(),trial=inPreseason()?TRIALS[c.preseason]:null,e=curEvent(),opp=!trial&&e?.t==='league'?G.clubs[leagueOpp(e.r)]:null,waiting=clubBeasts().filter(b=>b.rolls>0),locked=!armoryUnlocked();return `<div class="stack campaign-home">${journeyHtml()}<section class="campaign-bill"><div><span class="lbl gold">${trial?`PRESEASON · BOUT ${c.preseason+1} OF 4`:`${TIERS[G.tier].n} · SEASON ${G.season}`}</span><h2>${trial?trial.name:opp?'Your next challenger.':eventLabel(e)||'A season to remember.'}</h2><p>${trial?trial.tip:opp?`${esc(opp.name)} · 5 versus 5. Prepare your team and compete for gold and league points.`:'Choose your team for the cup. Every round is a chance to grow.'}</p><div class="row"><button class="btn pri" data-act="next">${trial?'Prepare this bout':'Prepare next match'} →</button><span class="note">${trial?`${trial.reward} gold · win or lose`:'Fight → earn → upgrade → repeat'}</span></div></div><div class="campaign-emblem">${crest(opp||G.clubs.P,116)}<span>${trial?'THE PROVING GROUNDS':opp?esc(opp.name):'YOUR LEGACY'}</span></div></section>
 ${waiting.length?`<section class="earned-upgrades"><div><span class="lbl gold">YOUR NEXT EDGE</span><h3>${waiting.length} beast${waiting.length>1?'s have':' has'} powers to choose</h3></div><button class="btn" data-act="profile" data-id="${waiting[0].id}" data-pt="skills">Choose an upgrade →</button></section>`:''}
 <div class="section-heading"><h2>Your menagerie</h2><button class="linkbtn" data-act="tab" data-k="roster">Manage the team →</button></div><div class="club-roster-strip">${clubBeasts().map(b=>`<button class="mini-beast-card" data-act="profile" data-id="${b.id}">${beastArt(b.sp)}${b.rolls?`<span class="upgrade-badge">${b.rolls}</span>`:''}<b>${esc(b.name)}</b><small>${SPECIES[b.sp].n}</small></button>`).join('')}</div>
 <div class="campaign-bottom"><section class="panel"><span class="lbl gold">${locked?'NEXT CLUB UNLOCK':'ARMORY OPEN'}</span><h3>${locked?'Earn your equipment.':'Outfit your champions.'}</h3><p class="note">${locked?'Compete in the arena to unlock equipment. Starting funds and sales do not count.':'Arena earnings opened the Armory. Buy a piece, then equip it on a beast.'}</p><div class="unlock-meter"><i style="width:${Math.min(100,c.earnedGold/3)}%"></i></div><div class="row between"><small>${Math.min(c.earnedGold,300)} / 300 arena gold</small>${locked?'':`<button class="linkbtn" data-act="tab" data-k="shop">Visit Armory →</button>`}</div></section><section class="panel"><span class="lbl gold">KEEPER’S NOTE</span><h3>One change. One more bout.</h3><p class="note">Earn free powers through combat. Rotate tired beasts, adjust your formation, then test your next idea.</p><div class="row"><button class="btn sm" data-act="keeperStart">Quick start</button><button class="btn sm" data-act="settings">Sound & settings</button></div></section></div></div>`};
const campaignTabs=renderTabs;renderTabs=function(){campaignTabs();if(!armoryUnlocked())document.querySelector('#tabs [data-k="shop"]')?.remove()};
const campaignTab=ACT.tab;ACT.tab=d=>{if(d.k==='shop'&&!armoryUnlocked())return;campaignTab(d)};
const campaignShop=viewShop;viewShop=function(){return armoryUnlocked()?campaignShop():`<section class="panel"><h2>Armory locked</h2><p>Earn ${ARMORY_EARNINGS} gold by competing in the arena.</p><button class="btn pri" data-act="tab" data-k="club">Back to your campaign</button></section>`};
for(const key of ['ibuy','cbuy','equip','unequip','use','isell','openArmory']){const fn=ACT[key];ACT[key]=(...args)=>{if(armoryUnlocked())return fn(...args)}}
const campaignProfile=modalProfile;modalProfile=function(m){const safe=!armoryUnlocked()&&m.pt==='gear'?{...m,pt:'overview'}:m;let html=campaignProfile(safe);if(!armoryUnlocked())html=html.replace(/<button[^>]*data-k="gear"[^>]*>[\s\S]*?<\/button>/g,'').replace('with skills and gear','with learned skills');return html};
const campaignIntro=viewIntro;viewIntro=function(){return campaignIntro().replace('Recruit, train, equip, and set each beast’s tactics. Fight 14 league matchdays and three cups per season.','Start with four short preseason bouts. Earn gold, choose powers, then tackle 14 league matchdays and three cups. Equipment unlocks after 300 arena gold.')};
readinessHtml=function(){const r=matchReadiness();return `<section class="panel match-readiness compact-readiness" data-guide="readiness"><div><span class="lbl gold">${r.selected.length} / ${r.required} SELECTED</span><h3>${r.full?'The arena is ready.':'Complete your lineup.'}</h3><p class="note">${r.tired.length?`Check fitness: ${r.tired.map(b=>esc(b.name)).join(', ')}.`:'Your beasts fight automatically. Watch at 1×; Space pauses.'}${r.held.length||r.partners.length?' Check held abilities and missing partners in Tactics.':''}</p></div><div class="match-launch"><button class="btn sm" data-act="go" data-w="0" ${r.full?'':'disabled'}>Quick result</button><button class="btn pri" data-act="go" data-w="1" ${r.full?'':'disabled'}>Enter the arena →</button></div></section>`};
// Keep the reward decision short; detailed techniques stay in the beast's Skills tab.
viewLevelUp=function(){const b=G.beasts[UI.lvq[0]],r=UI.result?.rows.find(x=>x.bid===b.id);let html=previousViewLevelUp().replace('Level up ·','New powers ·');if(!r?.ups)html=html.replace(/<div class="lvnum">[\s\S]*?<\/div>/,`<div class="lvnum">Arena power earned · level ${b.lvl}</div>`);return html};
